"""results.json -> docs/BENCHMARK.md (tables only; the narrative lives in docs/TECHNICAL_REPORT.md)."""
from __future__ import annotations


def _f(x, d=3):
    return "—" if x is None else (f"{x:.{d}f}" if isinstance(x, float) else str(x))


def write_markdown(R, path):
    L = ["# Benchmark report", "",
         "Every number below is regenerated by `python -m bench.run_benchmark` from `data/raw/`.",
         "", "**Ground truth status.** No tape or laser measurements exist for these captures yet. Tape-scored gates "
         "show as *pending* until `ground_truth/<space>.json` is filled in (template: `python -m bench.gates template`). "
         "The tables that need no ground truth are real gate measurements: repeatability, ceiling spread and the drift "
         "ablation. The cross-tier tables use the LiDAR result as a **pseudo-reference**. They measure agreement between "
         "tiers and how well the intervals are calibrated against LiDAR, not accuracy against the true room.", ""]
    # repeatability
    L += ["## Repeatability (two captures of the same rooms at the same tier)", "",
          "Gate: every wall within 1 cm or 0.5 %.", "",
          "| tier | rooms matched | walls matched | walls passing | median abs Δ | p90 abs Δ | gate |",
          "|---|---|---|---|---|---|---|"]
    for t, rep in R["repeatability"].items():
        if not rep:
            L.append(f"| {t} | not run | | | | | |")
            continue
        s = rep["summary"]
        ok = s["walls_matched"] > 0 and s["walls_pass"] == s["walls_matched"]
        L.append(f"| {t} | {s['rooms_matched']} | {s['walls_matched']} | {s['walls_pass']} | {_f(s['median_abs_delta_m'])} m | "
                 f"{_f(s['p90_abs_delta_m'])} m | {'PASS' if ok else 'FAIL'} |")
    lid = R["repeatability"].get("lidar")
    if lid:
        L += ["", "<details><summary>LiDAR per-wall repeatability</summary>", "",
              "| wall (capture A) | A (m) | B (m) | Δ (m) | Δ % | pass |", "|---|---|---|---|---|---|"]
        for w in lid["walls"]:
            L.append(f"| {w['wall_a']} | {w['len_a']:.3f} | {w['len_b']:.3f} | {w['delta_m']:+.3f} | {w['delta_pct']:+.2f} | "
                     f"{'✓' if w['pass_1cm_or_0.5pct'] else '✗'} |")
        L += ["", "</details>", "", "### Ceiling height (LiDAR)", "",
              "| room | capture A (m) | capture B (m) | spread (m) |", "|---|---|---|---|"]
        for rid, a, b, sp in lid["ceilings"]:
            L.append(f"| {rid} | {_f(a)} | {_f(b)} | {_f(sp)} |")
        L += ["", "Capture B (`floor_only`) never looks at the ceiling. The pipeline reports `null` with a lower bound "
              "rather than guessing, so the ceiling spread across captures cannot be measured on this data.", ""]
        if lid["openings"]:
            L += ["### Opening widths (LiDAR repeatability)", "", "| opening A | kind | A (m) | B (m) | Δ (m) |", "|---|---|---|---|---|"]
            for o in lid["openings"]:
                L.append(f"| {o['opening_a']} | {o['kind_a']} | {o['width_a']:.3f} | {o['width_b']:.3f} | {o['delta_m']:+.3f} |")
            L.append("")
    # drift
    D = R["drift_ablation"]
    L += ["## Drift ablation (LiDAR, multi-room)", "",
          "| capture | rooms on/off | floor area on/off (m²) | footprint bbox on | footprint bbox off |", "|---|---|---|---|---|"]
    for c, v in D.items():
        if c.startswith("repeatability"):
            continue
        L.append(f"| {c} | {v['rooms_on']}/{v['rooms_off']} | {v['area_on']:.2f} / {v['area_off']:.2f} | "
                 f"{v['bbox_on'][0]:.2f} × {v['bbox_on'][1]:.2f} | {v['bbox_off'][0]:.2f} × {v['bbox_off'][1]:.2f} |")
    if D.get("repeatability_on") and D.get("repeatability_off"):
        on, off = D["repeatability_on"], D["repeatability_off"]
        L += ["", f"Repeatability with drift correction **on**: median |Δ| {_f(on['median_abs_delta_m'])} m, "
              f"{on['walls_pass']}/{on['walls_matched']} walls pass. **Off**: median |Δ| {_f(off['median_abs_delta_m'])} m, "
              f"{off['walls_pass']}/{off['walls_matched']} walls pass.", ""]
    # cross tier
    L += ["## Video and photo tiers vs the LiDAR pseudo-reference", "",
          "Gates: video walls ±3 %, photo walls ±8 %, photo footprint ±8 %. Coverage is the fraction of LiDAR wall "
          "lengths that fall inside the tier's 95 % interval; well-calibrated intervals give about 0.95.", "",
          "| run | rooms (ref/run) | walls matched | median rel err | p90 rel err | 95 % CI coverage | footprint rel err |",
          "|---|---|---|---|---|---|---|"]
    for k, v in R["cross_tier_vs_lidar"].items():
        if not v:
            L.append(f"| {k} | not run | | | | | |")
            continue
        L.append(f"| {k} | {v['rooms_ref']}/{v['rooms_other']} | {v['walls_matched']} | {_f(v['median_rel_err'])} | "
                 f"{_f(v['p90_rel_err'])} | {_f(v['ci95_coverage_of_lidar'])} | {_f(v['footprint_rel_err'])} |")
    # GT gates
    L += ["", "## Tape and laser gates", ""]
    for space, v in R["ground_truth_gates"].items():
        if isinstance(v, str):
            L.append(f"- **{space}**: {v}")
        else:
            L += [f"### {space}", "", "| run | wall pass rate | ceiling max err | opening rate | CI coverage |", "|---|---|---|---|---|"]
            for run, g in v.items():
                L.append(f"| {run} | {_f(g.get('wall_pass_rate'))} | {_f(g.get('ceiling_max_abs_err_m'))} | "
                         f"{_f(g.get('opening_rate'))} | {_f(g.get('ci95_coverage'))} |")
    # timing
    L += ["", "## Timing (seconds, this machine: RTX 5060 Laptop 8 GB, 20 CPU threads)", "",
          "| run | total | breakdown |", "|---|---|---|"]
    for k, t in R["timing_s"].items():
        br = ", ".join(f"{a} {b}" for a, b in t.items() if a != "total")
        L.append(f"| {k} | {t.get('total', '—')} | {br} |")
    open(path, "w").write("\n".join(L) + "\n")
